create view IF NOT EXISTS ECOSURE_RESTAURANT_AUDIT_BV(
	BRAND_ID COMMENT 'Brand Identifier specifies the code which represents an organization. The identifier should be in all capital letters. Sample codes are irb (Inspire Recognized Brands), bww(Buffalo Wild Wing), arbys (Arbys),  dnkn  (Dunkin), etc.',
	ECOSURE_AUDIT_ID COMMENT 'Ecosure Audit Identifier is a unique integer value to identify an audit.',
	AUDIT_DT COMMENT 'Audit Date is the day of the audit.',
	ECOSURE_CONCEPT_NBR COMMENT 'ECOSURE CONCEPT NUMBER is a location attribute. Sample value ARB.',
	STORE_ID COMMENT 'Store Identifier is an integer that uniquely identifies the store.',
	ECOSURE_AUDITOR_ID COMMENT 'ECOSURE AUDITOR IDENTIFIER uniquely identifies an indvidual auditor.',
	ECOSURE_CYCLE_QTY COMMENT 'ECOSURE CYCLE QUANTITY is the number of rounds of an audit.',
	ECOSURE_VISIT_QTY COMMENT 'ECOSURE VISIT QUANTITY is the count of visits within a cycle.',
	ECOSURE_REFERENCE_NBR COMMENT 'ECOSURE REFERENCE NUMBER is the Internal EcoSure program number. Sample value AY2018.',
	ECOSURE_NOTE_TXT COMMENT 'ECOSURE NOTE TEXT are audit level notes.',
	ECOSURE_STORE_ID COMMENT 'ECOSURE STORE IDENTIFIER si the unique EcoSure location id.',
	ECOSURE_FORM_NM COMMENT 'ECOSURE FORM NAME is the program audit form name. Sample value Arby''s Safety First (S).',
	SOURCE_SYSTEM_NM COMMENT 'Source System Name specifies the origin of the data. For example, Salesforce Marketing App or Netsuite. Some systems will have a reference table where sources are identified by integers such as 1,2,3, etc.',
	LOAD_ID COMMENT 'Load Identifier specifies the Batch that inserted the record into the table.',
	LOAD_DTTM COMMENT 'Load Datetime is the date and time in UTC when the record was created. For example, 2021-08-11T15:02:24Z.',
	UPDATE_ID COMMENT 'Update Identifier specifies the batch id used for the update of the record.',
	UPDATE_DTTM COMMENT 'Update Datetime is the date and time in UTC when the record was last updated. For example, 2021-08-11T15:02:24Z.'
) COMMENT='ECOSURE_RESTAURANT_AUDIT identifies the audit level information for a particular store that is sourced from ECOSURE.'
 as 
SELECT ECOSURE_RESTAURANT_AUDIT.BRAND_ID,ECOSURE_RESTAURANT_AUDIT.ECOSURE_AUDIT_ID,ECOSURE_RESTAURANT_AUDIT.AUDIT_DT,ECOSURE_RESTAURANT_AUDIT.ECOSURE_CONCEPT_NBR,ECOSURE_RESTAURANT_AUDIT.STORE_ID,ECOSURE_RESTAURANT_AUDIT.ECOSURE_AUDITOR_ID,ECOSURE_RESTAURANT_AUDIT.ECOSURE_CYCLE_QTY,ECOSURE_RESTAURANT_AUDIT.ECOSURE_VISIT_QTY,ECOSURE_RESTAURANT_AUDIT.ECOSURE_REFERENCE_NBR,ECOSURE_RESTAURANT_AUDIT.ECOSURE_NOTE_TXT,ECOSURE_RESTAURANT_AUDIT.ECOSURE_STORE_ID,ECOSURE_RESTAURANT_AUDIT.ECOSURE_FORM_NM,ECOSURE_RESTAURANT_AUDIT.SOURCE_SYSTEM_NM,ECOSURE_RESTAURANT_AUDIT.LOAD_ID,ECOSURE_RESTAURANT_AUDIT.LOAD_DTTM,ECOSURE_RESTAURANT_AUDIT.UPDATE_ID,ECOSURE_RESTAURANT_AUDIT.UPDATE_DTTM
FROM IDS_DEV.LOCN.ECOSURE_RESTAURANT_AUDIT ;
create view IF NOT EXISTS ECOSURE_RESTAURANT_AUDIT_SCORE_BV(
	BRAND_ID COMMENT 'Brand Identifier specifies the code which represents an organization. The identifier should be in all capital letters. Sample codes are irb (Inspire Recognized Brands), bww(Buffalo Wild Wing), arbys (Arbys),  dnkn  (Dunkin), etc.',
	ECOSURE_AUDIT_ID COMMENT 'Ecosure Audit Identifier is a unique integer value to identify an audit.',
	ECOSURE_SCORE_NM COMMENT 'ECOSURE SCORE NAME is the label for the score. Sample value: Overall Score.',
	ECOSURE_SCORE_AMT COMMENT 'ECOSURE SCORE AMOUNT is a decimal value from 0 to 100. Sample Values 93.4, 82, and 62.8.',
	ECOSURE_RATING_VAL COMMENT 'ECOSURE RATING VALUE a single letter value denoting the score. Sample Values A, B, C, and F.',
	ECOSURE_IN_COMPLIANCE_QTY COMMENT 'ECOSURE IN COMPLIANCE QUANTITY is the count of items in compliance.',
	ECOSURE_OUT_OF_COMPLIANCE_QTY COMMENT 'ECOSURE OUT OF COMPLIANCE QUANTITY  is the count of items in out of compliance.',
	SOURCE_SYSTEM_NM COMMENT 'Source System Name specifies the origin of the data. For example, Salesforce Marketing App or Netsuite. Some systems will have a reference table where sources are identified by integers such as 1,2,3, etc.',
	LOAD_ID COMMENT 'Load Identifier specifies the Batch that inserted the record into the table.',
	LOAD_DTTM COMMENT 'Load Datetime is the date and time in UTC when the record was created. For example, 2021-08-11T15:02:24Z.',
	UPDATE_ID COMMENT 'Update Identifier specifies the batch id used for the update of the record.',
	UPDATE_DTTM COMMENT 'Update Datetime is the date and time in UTC when the record was last updated. For example, 2021-08-11T15:02:24Z.'
) COMMENT='ECOSURE_RESTAURANT_AUDIT SCORE contains the scores at an audit aggregate level for a store that is sourced from ECOSURE.'
 as 
SELECT ECOSURE_RESTAURANT_AUDIT_SCORE.BRAND_ID,ECOSURE_RESTAURANT_AUDIT_SCORE.ECOSURE_AUDIT_ID,ECOSURE_RESTAURANT_AUDIT_SCORE.ECOSURE_SCORE_NM,ECOSURE_RESTAURANT_AUDIT_SCORE.ECOSURE_SCORE_AMT,ECOSURE_RESTAURANT_AUDIT_SCORE.ECOSURE_RATING_VAL,ECOSURE_RESTAURANT_AUDIT_SCORE.ECOSURE_IN_COMPLIANCE_QTY,ECOSURE_RESTAURANT_AUDIT_SCORE.ECOSURE_OUT_OF_COMPLIANCE_QTY,ECOSURE_RESTAURANT_AUDIT_SCORE.SOURCE_SYSTEM_NM,ECOSURE_RESTAURANT_AUDIT_SCORE.LOAD_ID,ECOSURE_RESTAURANT_AUDIT_SCORE.LOAD_DTTM,ECOSURE_RESTAURANT_AUDIT_SCORE.UPDATE_ID,ECOSURE_RESTAURANT_AUDIT_SCORE.UPDATE_DTTM
FROM IDS_DEV.LOCN.ECOSURE_RESTAURANT_AUDIT_SCORE ;
