	L1ID,
	L1NAME,
	L1MANAGERID,
	L1MANAGER,
	L2ID,
	L2NAME,
	L2MANAGERID,
	L2MANAGER,
	L3ID,
	L3NAME,
	L3MANAGERID,
	L3MANAGER,
	L4ID,
	L4NAME,
	L4MANAGERID,
	L4MANAGER,
	L5ID,
	L5NAME,
	L5MANAGERID,
